$rows=$con->query("SELECT l.id,p.patientname,COALESCE(d.doctorname,'') doctorname,l.test_name,l.category,l.status,l.result,l.requested_at,l.completed_at FROM lab_requests l JOIN patient p ON p.patientid=l.patient_id LEFT JOIN doctor d ON d.doctorid=l.doctor_id ORDER BY l.id DESC");
$filename='laboratory_report_'.date('Ymd_His').'.xlsx';
