$tpl=__DIR__.'/excel_templates/laboratory.xlsx';$styles='';$headerStyle=1;$titleStyle=0;$subStyle=0;$dateStyle=0;$tz=new ZipArchive();if(is_file($tpl)&&$tz->open($tpl)===true){$styles=(string)$tz->getFromName('xl/styles.xml');$tx=(string)$tz->getFromName('xl/worksheets/sheet1.xml');foreach([['A1','titleStyle'],['A2','subStyle'],['A3','dateStyle']] as $x){if(preg_match('/<c[^>]*r="'.$x[0].'"[^>]*s="(\\d+)"/',$tx,$m))${$x[1]}=(int)$m[1];}if(preg_match('/<c[^>]*r="A5"[^>]*s="(\\d+)"/',$tx,$m))$headerStyle=(int)$m[1];$tz->close();}
